package id.imperial.resourcepack.common;
import com.sun.net.httpserver.*;import java.io.*;import java.net.*;import java.nio.file.*;import java.util.concurrent.Executor;import java.util.logging.Logger;
/** JDK HTTP server that exposes only the current validated resource pack. */
public final class ResourcePackHost implements AutoCloseable {private final ResourcePackManager manager;private final Logger logger;private HttpServer server;public ResourcePackHost(ResourcePackManager m,Logger l){manager=m;logger=l;}public synchronized boolean start(ResourcePackConfig c,Executor x){close();if(!c.hostingEnabled())return false;try{server=HttpServer.create(new InetSocketAddress(c.bind(),c.port()),0);server.createContext(c.hostPath(),this::pack);server.createContext("/status",this::status);server.setExecutor(x);server.start();logger.info("[ImperialResourcePack] HTTP server listening on "+c.bind()+":"+c.port());return true;}catch(IOException e){logger.severe("[ImperialResourcePack] ERROR: HTTP server could not start: "+e.getMessage());server=null;return false;}}private void pack(HttpExchange e)throws IOException{if(!e.getRequestMethod().equals("GET")&&!e.getRequestMethod().equals("HEAD")){e.sendResponseHeaders(405,-1);return;}ActivePack p=manager.active();if(p==null){e.sendResponseHeaders(503,-1);return;}e.getResponseHeaders().set("Content-Type","application/zip");e.getResponseHeaders().set("Content-Length",String.valueOf(p.size()));e.sendResponseHeaders(200,e.getRequestMethod().equals("HEAD")?-1:p.size());if(e.getRequestMethod().equals("GET"))try(InputStream in=Files.newInputStream(p.file());OutputStream out=e.getResponseBody()){in.transferTo(out);}else e.close();}private void status(HttpExchange e)throws IOException{ActivePack p=manager.active();byte[] b=(p==null?"{\"active\":false}":"{\"active\":true,\"sha1\":\""+p.sha1Hex()+"\"}").getBytes();e.getResponseHeaders().set("Content-Type","application/json");e.sendResponseHeaders(200,e.getRequestMethod().equals("HEAD")?-1:b.length);if(e.getRequestMethod().equals("GET"))try(OutputStream o=e.getResponseBody()){o.write(b);}else e.close();}public synchronized boolean running(){return server!=null;}public synchronized void close(){if(server!=null){server.stop(1);server=null;}}}
